DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.manage_customer_booking(uuid,text,text,integer,date,text)'::regprocedure) INTO def; def:=replace(def,'FUNCTION public.manage_customer_booking(','FUNCTION public.manage_customer_booking_v2('); EXECUTE def; END $$;
REVOKE ALL ON FUNCTION public.manage_customer_booking_v2(uuid,text,text,integer,date,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.manage_customer_booking_v2(uuid,text,text,integer,date,text) TO service_role;
CREATE OR REPLACE FUNCTION public.manage_customer_booking(_token uuid,_action text,_time text DEFAULT NULL,_people integer DEFAULT NULL) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.manage_customer_booking_v2(_token,_action,_time,_people,NULL::date,NULL::text) $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.decide_customer_change(uuid,uuid,boolean,jsonb,uuid[],jsonb,text)'::regprocedure) INTO def; def:=replace(def,'OR r.arrived OR r.tavolo_bloccato OR r.modification_status','OR r.arrived OR (_accept AND r.tavolo_bloccato) OR r.modification_status'); EXECUTE def; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.get_online_booking_page(text)'::regprocedure) INTO def; def:=replace(def,'''enable_double_shift'',r.enable_double_shift','''online_turns_override'',r.online_turns_override,''enable_double_shift'',r.enable_double_shift'); EXECUTE def; END $$;